  2192
  2193      if (activeTimestamp.GetLength() == 0 || netif.GetActiveDataset().Compare(activeTimestamp) != 0)
  2194      {
  2195          child->SetRequestTlv(numTlvs++, Tlv::kActiveDataset);
  2196      }
  2197
  2198      if (pendingTimestamp.GetLength() == 0 || netif.GetPendingDataset().Compare(pendingTimestamp) != 0)
  2199      {
  2200          child->SetRequestTlv(numTlvs++, Tlv::kPendingDataset);
  2201      }
